function notify(text){const n=document.getElementById('notice');n.textContent=text;n.classList.add('show');clearTimeout(window.noteTimer);window.noteTimer=setTimeout(()=>n.classList.remove('show'),2100)}
function install(type,index){const p=partObj(type,index);if(state.level<p.unlock){notify(`Unlocks at workshop level ${p.unlock}`);return}if(selected(type)===index){removePart(type);return}let refund=selected(type)==null?0:partObj(type,selected(type)).price;let price=p.price-refund;if(price>state.credits){notify('Not enough credits for that component');return}state.credits-=price;state.installed[type]=index;save();render()}
function removePart(type){if(selected(type)===null)return;state.credits+=partObj(type,selected(type)).price;delete state.installed[type];save();render()}
function benchmark(){if(!complete())return;const j=job(),ok=meets(),cost=totalCost(),cash=ok?j.reward+j.bonus:Math.round(j.reward*.45);state.credits+=cash;state.rep+=ok?1:0;state.xp+=100;state.level=Math.min(4,1+Math.floor(state.xp/100));state.completed++;state.feed.unshift({title:ok?'Order completed — '+j.title:'Build needs work — '+j.title,detail:`${ok?'Perfect spec match · bonus earned':'Partial payout · review specs'} · +$${cash.toLocaleString()}`});state.feed=state.feed.slice(0,8);state.installed={};save();render();showResult(ok,j,cost,cash)}
function showResult(ok,j,cost,cash){let wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal"><div class="modal-icon">${ok?'🏆':'🛠️'}</div><div class="eyebrow">${ok?'BENCHMARK PASSED':'BENCHMARK COMPLETE'}</div><h2>${ok?'Beautiful build!':'Needs a little tuning.'}</h2><p>${ok?'Every spec checked out. Your customer is thrilled, and you earned the perfect-build bonus.':'The PC runs, but it missed one or more requested specs. You still earned a partial payout. Check the next order carefully.'}</p><div class="result-line"><span>Parts investment</span><strong style="color:#eee">$${cost}</strong></div><div class="result-line"><span>Customer payout</span><strong>+$${cash}</strong></div><div class="result-line"><span>Workshop reputation</span><strong>${ok?'+1 star':'No change'}</strong></div><div class="result-line"><span>Workshop level</span><strong>LVL ${state.level}</strong></div><button class="action-btn" onclick="this.closest('.modal-backdrop').remove()">${state.job>=JOBS.length?'KEEP BUILDING':'NEXT ORDER'} &nbsp;→</button></div>`;wrap.addEventListener('click',e=>{if(e.target===wrap)wrap.remove()});document.body.appendChild(wrap)}
function resetGame(){if(!confirm('Reset your career and start over?'))return;localStorage.removeItem('pcsim-save');state=fresh();render();notify('Career reset — welcome to the workshop')}
render();
</script></body></html>

